-- 分解界面说明文字
_Decompose_tip_info = "1.“+”를 눌러 선택 화면으로 이동하며, 한 번에 최대 5개의 닌자, 장비, 보물 또는 코스튬을 선택해 분해할 수 있습니다.\r\n2. 4성 이상이며 성장하지 않은 닌자만 분해할 수 있으며, 분해 시 모든 강화 비용을 돌려받고 수혼을 획득합니다.\r\n3. 3성과 4성 장비를 분해할 수 있으며, 분해 시 모든 강화 비용을 돌려받고 각성서를 획득합니다.\r\n4. 5성 장비를 분해할 수 있으며, 분해 시 모든 강화 비용을 돌려받고 주황 장비 제작 재료를 획득합니다.\r\n5. 5성 보물만 분해할 수 있으며, 분해 시 영기 정수를 획득하고 모든 강화 경험치를 돌려받습니다(돌려받은 경험치는 분해로 얻은 파란색 경험치 보물에 포함됩니다)\r\n6.코스튬을 분해하면 코스튬 정수를 획득합니다\r\n7.분해한 닌자, 장비, 보물 또는 코스튬은 사라집니다."


-- 退化界面说明文字
_Regeneration_tip_info = "1.“+”를 눌러 선택 화면으로 이동하며, 한 번에 1개의 닌자, 장비, 보물 또는 코스튬만 선택해 퇴화할 수 있습니다.\r\n2.강화 레벨이 2레벨 이상인 4성 닌자와 5성 닌자를 퇴화할 수 있으며, 퇴화 시 모든 비용을 돌려받습니다(성장에 소모한 구리 동전은 돌려받지 않음). 퇴화한 닌자는 성장 단계가 0단계로, 강화 레벨이 1레벨로 돌아갑니다.\r\n3. 6성 닌자를 퇴화할 수 있으며, 퇴화 후 5성+7이 되고 레벨은 유지되며, 성장과 주황 성장에 소모한 모든 구리 동전과 재료를 돌려받습니다.\r\n4. 5성이며 강화 레벨이 0보다 큰 장비만 퇴화할 수 있으며, 퇴화 시 모든 강화 비용을 돌려받고 세련 속성에 따라 각성서를 돌려받습니다.\r\n5.강화 레벨이 0보다 큰 코스튬만 퇴화할 수 있으며, 퇴화 시 모든 강화 비용과 코스튬 정수를 돌려받습니다.\r\n6. 4성 이상이며 강화한 보물만 퇴화할 수 있으며, 퇴화 시 모든 강화 비용을 돌려받고 보물 레벨에 따라 경험치 보물과 각성 보물을 돌려받습니다\r\n7.퇴화할 때마다 일정량의 골드가 필요합니다."


-- 灵异探险界面的说明文字
_Divine_explain_tip_info = "1.목표 도안의 모든 도안을 밝히거나 아무 도안이나 클릭하면 별 개수 보상을 획득할 수 있습니다.\r\n\r\n2.획득한 별 개수로 보상을 교환할 수 있으며, 별이 많을수록 더 많은 보상을 교환할 수 있습니다.\r\n\r\n3.매일 새벽 0시에 탐험 횟수, 현재 별 개수 및 보상이 초기화됩니다."

-- 限时队长级说明文字
_Limited_hero_tip_info = "1.이벤트 화면에서 무료 소환 또는 골드 소환으로 닌자를 뽑으면 10포인트를 획득합니다.\r\n2.포인트를 150점 모을 때마다 무료 골드 소환 1회를 획득합니다.\r\n3.소환할 때마다 4성 또는 5성 닌자를 무작위로 획득하며, 5성 닌자에는 기간 한정 이벤트 닌자가 포함됩니다.\r\n4.이벤트 종료 시 포인트 순위에 따라 순위 보상이 지급됩니다.\r\n5.포인트가 1000점에 도달할 때마다 현재 기간 한정 리더를 반드시 획득합니다.\r\n6.포인트가 60점에 도달한 플레이어는 추가로 금 경험치 짐승 10개, 구리 동전 20만, 성장석 500개를 획득합니다(이 보상은 순위 보상과 함께 받을 수 있습니다)\r\n이벤트가 끝난 당일 내에 보상이 지급되며, 보상 센터에서 수령할 수 있습니다."

-- 超级变变变说明文字(限时兑换)
_Super_change_tip_info = "1.이벤트 기간 동안 플레이어는 지정된 아이템을 사용해 교환하여 새로운 아이템을 획득할 수 있습니다;\r\n2.강화된 적 없는 장비나 보물을 사용해 교환할 수 있습니다;\r\n3.교환 후에는 기존 아이템을 잃고 교환한 새 아이템을 획득합니다."

-- 分段折扣说明文字
_Divide_sell_tip_info = "1.이벤트 기간 동안 전체 서버에서 구매한 지정 아이템 수량에 따라 해당 아이템이 할인됩니다.\r\n2.지정 아이템의 소모 수량이 지정 수량에 도달하면 상점에서 판매하는 해당 아이템의 가격도 그에 맞게 변경됩니다.\r\n"

-- 跨服幸运大转盘说明文字
_Luck_turntable_tip_info = "1.이벤트 기간에 무료 또는 골드로 행운의 룰렛을 돌리면 1포인트를 얻으며, 이벤트 종료 후 포인트 순위에 따라 보상이 지급됩니다;\r\n2.무료 횟수는 누적되지 않으며, 사용 후 12시간이 지나면 회복됩니다;\r\n3.이벤트 기간에 무료 또는 골드로 행운의 룰렛을 돌리면 횟수 보상 진행 바가 한 칸씩 늘어나며, 해당 횟수에 도달하면 즉시 보상을 받을 수 있습니다;\r\n4.매일 5회 무료 새로고침으로 룰렛의 보상을 새로 고칠 수 있으며, 무료 횟수를 다 쓰면 골드로 새로 고칠 수 있습니다. 플레이어가 고급 아이템을 뽑으면 룰렛이 강제로 새로 고쳐집니다;\r\n5.무료 새로고침이나 골드 새로고침 모두 고급 한정 아이템이 나올 수 있습니다(한정 아이템이 매진되면 더 이상 나오지 않음);\r\n6.무료 또는 골드로 행운의 룰렛을 돌리면 행운의 대상을 받을 기회가 있습니다;\r\n7.시스템은 플레이어가 룰렛을 돌리며 소모한 골드의 일정 비율을 행운의 대상 상금 풀에 누적하며, 누적에는 상한이 없습니다;\r\n8.플레이어가 행운의 대상에 당첨되면 상금 풀 골드의 일정 비율을 독차지합니다;\r\n9.행운의 룰렛 데이터는 모든 서버에서 공유됩니다."

-- 灵王宫说明文字
_spirite_palace_tip_info = "1.매일 무료 초기화 기회를 한 번 얻습니다(누적 불가)；\r\n2.신비의 궁전은 총 다섯 층으로, 각 층에서 이동 가능 횟수 상한에 도달하면 다음 층 입구가 나타나며, 다섯 번째 층 종점에 도달하면 이번 탐험이 완료됩니다；\r\n3.갈림길의 이벤트 아이콘을 누르면 이벤트 설명을 볼 수 있으며, 이동을 누르면 해당 이벤트가 발동합니다. 또는 아래 화살표를 눌러 바로 이동할 수 있습니다；\r\n4.이벤트를 하나 발동할 때마다 일정 포인트를 얻으며, 포인트는 신비의 궁전 상점에서 아이템으로 교환할 수 있습니다；\r\n5.이동할 때마다 행동력 1이 소모되며, 행동력이 0이면 더 이상 이동할 수 없습니다；\r\n6.신비의 궁전에 처음 들어가거나 초기화한 후 플레이어의 현재 진형에 따라 탐험 진형이 정해지며, 한 번 정해진 탐험 진형은 이번 탐험 중 변경할 수 없습니다；\r\n7.신비의 궁전에 처음 들어가거나 초기화한 후 플레이어의 현재 진형 모든 닌자 생명력 합계의 세 배로 체력 게이지가 생성됩니다. 탐험 중 전투를 만나게 되며, 전투가 끝나면 닌자가 잃은 생명력만큼 게이지를 소모해 보충합니다. 게이지가 0이 되면 더 이상 탐험할 수 없습니다."

-- 跨服战说明文字
_cross_server_tip_info = "【전투 정보 갱신】\r\nA)전투 정보\r\n플레이어의 전투와 관련된 데이터, 즉 출전 닌자, 장비, 비술, 진형 등 플레이어의 전투력에 영향을 주는 모든 정보를 말합니다.\r\nB)전투 정보 갱신\r\n전투 정보를 변경할 때마다 “전투 정보 갱신”을 눌러 차원 쟁패전 게임 서버에 최신 전투 정보를 업로드해야 합니다. 그렇지 않으면 게임 서버의 플레이어 전투 정보는 바뀌지 않습니다.\r\n【차원 쟁패전 규칙】\r\nA)선공 규칙\r\n전투력이 높은 플레이어가 선공합니다\r\nB)예선 규칙\r\n1、정예조 예선 규칙\r\n1)상대는 무작위로 배정되며, 경기당 1판, 경기 간격은 10분입니다\r\n2)이미 탈락한 상대와는 다시 만나지 않습니다\r\n3)누적 3패 시 탈락하며, 최종 32강이 가려질 때까지 진행됩니다\r\n4)내 정보의 “내 전적”에서 자신의 전적을 확인할 수 있습니다\r\n2、도전조 예선 규칙\r\n1)정예조 예선이 끝나면 정예조 진출자를 제외한 나머지 플레이어가 도전조 예선을 치릅니다\r\n2)상대는 무작위로 배정되며, 경기당 1판, 경기 간격은 10분입니다\r\n3)이미 탈락한 상대와는 다시 만나지 않습니다\r\n4)누적 3패 시 탈락하며, 최종 32강이 가려지면 예선이 끝납니다\r\n5)내 정보의 “내 전적”에서 자신의 전적을 확인할 수 있습니다\r\nC)본선 규칙\r\n1、예선을 통과한 정예조 32강과 도전조 32강을 16개 조로 나누어, 조마다 2명이 5판 3선승제로 겨루며 3승을 거둔 플레이어가 진출합니다. 판 간격은 20분입니다\r\n2、본선 경기 간격은 1일입니다\r\n3、정예조와 도전조에서 각각 우승자를 가립니다\r\n4、본선에 진출한 플레이어는 자동으로 크로스 서버 차원 쟁패전 예선에 참가합니다\r\n【크로스 서버 차원 쟁패전 규칙】\r\nA)선공 규칙\r\n전투력이 높은 플레이어가 선공합니다\r\nB)예선 규칙\r\n1、정예조 예선 규칙\r\n1)상대는 무작위로 배정되며, 경기당 1판, 경기 간격은 10분입니다\r\n2)이미 탈락한 상대와는 다시 만나지 않습니다\r\n3)누적 3패 시 탈락하며, 최종 32강이 가려질 때까지 진행됩니다\r\n4)내 정보의 “내 전적”에서 자신의 전적을 확인할 수 있습니다\r\n2、도전조 예선 규칙\r\n1)정예조 예선이 끝나면 정예조 진출자를 제외한 나머지 플레이어가 도전조 예선을 치릅니다\r\n2)상대는 무작위로 배정되며, 경기당 1판, 경기 간격은 10분입니다\r\n3)이미 탈락한 상대와는 다시 만나지 않습니다\r\n4)누적 3패 시 탈락하며, 최종 32강이 가려지면 예선이 끝납니다\r\n5)내 정보의 “내 전적”에서 자신의 전적을 확인할 수 있습니다\r\nC)본선 규칙\r\n1、예선을 통과한 정예조 32강과 도전조 32강을 16개 조로 나누어, 조마다 2명이 5판 3선승제로 겨루며 3승을 거둔 플레이어가 진출합니다. 판 간격은 20분입니다\r\n2、본선 경기 간격은 1일입니다\r\n3、정예조와 도전조에서 각각 우승자를 가립니다\r\n4、크로스 서버 차원 쟁패전 정예조 우승자가 속한 서버의 모든 플레이어는 선물 보상을 받을 수 있습니다\r\n【응원 규칙】\r\n본선 단계에서는 본선 경기마다 플레이어 1명만 응원할 수 있으며, 응원한 플레이어가 다음 라운드에 진출하면 응원 보상을 받습니다. 각 본선 경기가 끝난 후 응원 보상이 지급되며, 지급이 완료되면 다음 본선 경기를 응원할 수 있습니다."

-- 副队长说明文字
_vice_captain_tip_info = "1.출전 중인 부대장은 일정 시간마다 일정량의 경험치를 얻습니다；\r\n2.출전 중인 부대장만 출격할 수 있으며, 출격한 부대장은 전투 전에 자신의 스킬 속성을 출전 닌자에게 제공할 수 있습니다；\r\n3.한 번에 부대장 한 명만 출격할 수 있습니다；\r\n4.육성으로 부대장 경험치를 늘릴 수 있으며, 부대장이 일정 레벨에 도달하면 스킬 포인트를 얻습니다；\r\n5.스킬 포인트는 스킬 슬롯 개방, 스킬 습득, 스킬 업그레이드에 사용할 수 있습니다."

--侵略者帮助奖励文字
_betray_army_reward_tip_info = "1.히카리가오카 수호로 공훈 보상을 얻을 수 있으며, 주로 대량의 구리 동전, 칩석, 주황색 경험치 보물입니다.\r\n2.히카리가오카 수호로 전공도 얻을 수 있으며, 전공은 전공 상점에서 희귀 닌자와 칩석 구매에 사용할 수 있습니다."

--侵略者帮助功勋文字
_betray_army_exploit_tip_info = "1.35레벨 이후 메인 던전과 엘리트 던전에 도전할 때마다 일정 확률로 침략자를 발견하며, 혼자 또는 친구를 초대해 함께 히카리가오카를 수호할 수 있습니다.\r\n2.히카리가오카 수호 때마다 공훈치를 얻으며, 데미지가 높을수록 공훈치가 많아집니다. 닌자 성장 +1마다 침략자에게 주는 데미지가 2.5배 증가합니다!\r\n3.침략자를 처치하면 침략자를 발견한 플레이어와 마지막 일격을 가한 플레이어 모두 골드 보상을 얻습니다."

--侵略者帮助战功文字
_betray_army_credit_tip_info = "1.침략자를 공격할 때, 도전장을 하나 소모할 때마다 전공 50을 획득합니다.\r\n2.빛의 수호의 일일 공훈 순위와 일일 데미지 순위 상위 200위 안에 들면 추가 순위 전공 보상도 획득할 수 있습니다.\r\n3.매일 12:00~14:00 분노 공격은 도전장을 1개만 소모하며, 18:00~20:00에는 침략자 공격 공훈이 두 배가 됩니다."

--组织资源抢夺帮助信息
_capture_resource_tip_info = "1.건물 수비자를 물리치면 해당 건물을 점령하고 자원 생산 보상을 얻을 수 있습니다;\r\n2.플레이어는 여러 건물을 동시에 점령할 수 있으며, 인접한 건물은 자원 생산 보너스를 얻습니다;\r\n3.건물마다 점령 조건이 있으며, 건물 점령 진형은 임시로 구성하는 진형으로 기존 진형과 독립적입니다;\r\n4.기존 진형에 출전 중인 닌자를 파견할 수 있으며, 장비와 보물 속성은 계산되지 않고 인연은 새 출전 상황에 따라 다시 계산됩니다;\r\n5.점령에 성공하면 파견한 닌자는 건물 수비대가 되며, 도중에 교체할 수 없습니다;\r\n6.건물을 공격하거나 점령하면 포인트를 얻으며, 매주 화요일과 금요일 낮 12시에 포인트 순위에 따라 보상을 지급하고 포인트를 초기화합니다;\r\n7.건물 공격은 승패와 관계없이 5포인트를 얻으며, 건물 점령 후에는 매분 1포인트를 얻습니다(점령 종료 시 점령 시간에 따라 지급);\r\n8.순위 보상은 플레이어가 직접 보상 페이지에 들어가 수령해야 하며, 다음 순위 정산까지 보관됩니다. 정산 시 수령하지 않은 보상은 삭제됩니다(포인트가 0인 플레이어는 보상을 받을 수 없음)."

---组织战帮助信息
_union_fight_tip_info = "신청 단계：\r\n1.수요일 3시에 신청이 시작됩니다；\r\n2.조직에 가입한 지 48시간이 지난 멤버만 조직전에 참여할 수 있습니다；\r\n3.조직전은 크로스 서버 전투이며, 조직 전투력에 따라 상대가 매칭됩니다.\r\n\r\n준비 단계：\r\n1.목요일 3시에 준비 단계가 시작됩니다；\r\n2.수장과 부수장은 방어 진형을 배치할 수 있습니다；\r\n3.조직 멤버는 전방 성과 후방 성에 각각 방어 칸을 하나씩 가집니다；\r\n4.숨겨진 칸은 공격받기 전까지 정보가 공개되지 않습니다.\r\n\r\n전투 단계：\r\n1.금요일 3시에 전투가 시작되고 22시에 전투를 정산합니다；\r\n2.각자 공격 시도 기회 3회, 처치 횟수 2회가 주어집니다；\r\n3.수비가 1인 거점은 【함락 직전】 상태가 되어 통과할 수 있습니다；\r\n4.수비가 0인 거점은 【점령】 상태가 되어 포인트를 얻을 수 있습니다；\r\n5.특수 거점에는 추가 보상이 있으며, 해당 거점을 점령하면 수령할 수 있습니다；\r\n6.정산 시 포인트가 높은 조직이 승리하며, 포인트가 같으면 전투력이 낮은 조직이 승리합니다；\r\n7.승리한 조직과 패배한 조직 모두 보상을 받으며, 패배 보상은 승리 보상의 절반입니다."


