	{3,"경기장 1000위 진입","뜻이 있는 곳에 길이 있다! 끈질긴 노력 끝에 드디어 《닌자왕》 경기장 1000위 안에 들었어요! 제 이름은 %s, %s 서버에 있어요. 안 알려줬다고 하지 마세요, 같이 놀아요!"},------------------------------
	{4,"주황색 닌자 획득","《닌자왕》의 주황색 닌자는 역시 대단해요! 방금 강력한 주황색 닌자를 얻었어요. 제 이름은 %s, %s 서버에 있어요. 안 알려줬다고 하지 마세요, 같이 놀아요!"},------------------
	{5,"주인공 Lv.30 달성","눈 깜짝할 사이에 제 《닌자왕》 주인공이 30레벨이 됐어요! 정말 짜릿해요! 제 이름은 %s, %s 서버에 있어요. 안 알려줬다고 하지 마세요, 같이 놀아요!"},-------------------------------
	{6,"메인 스토리 8장 클리어","방금 세 명의 강자와 함께 대두목을 쓰러뜨렸어요! 못 믿겠다면 《닌자왕》에 와서 확인해 보세요! 제 이름은 %s, %s 서버에 있어요. 안 알려줬다고 하지 마세요, 같이 놀아요!"},--------------------------------
	{7,"주인공 Lv.50 달성","제 《닌자왕》 주인공이 50레벨이 됐어요! 전투력이 한층 더 올랐어요! 제 이름은 %s, %s 서버에 있어요. 안 알려줬다고 하지 마세요, 같이 놀아요!"},-----------------------------
	{8,"경기장 1위 달성","무릎 꿇고 경배하라! 본좌는 경기장 최강의 자리에 올랐다! 《닌자왕》에 와서 내 위엄을 보아라! 제 이름은 %s, %s 서버에 있어요. 안 알려줬다고 하지 마세요, 같이 놀아요!"},-------------------------
