national_truce_dec =  --国战说明
{
	{"[규칙]","세력전 영토는 용호문 영토, 백련교 영토, 나찰교 영토, 중립 지대의 4개 구역으로 나뉩니다."},
	{"","각 세력에는 주신상이 하나씩 있으며, 주신상은 함락되지 않습니다. 플레이어는 전사하면 주신상으로 이동해 부활합니다."},
	{"","거점의 마지막 NPC를 처치하면 그 유저가 속한 세력이 거점을 점령한 것으로 간주됩니다. 이벤트 기간 중 이미 점령된 거점도 계속 빼앗을 수 있습니다."},
	{"","같은 거점을 두 개 이상의 세력이 동시에 다투는 경우, 해당 거점 범위 안의 유저는 거점을 지키는 NPC도 공격할 수 있고 거점을 공격 중인 다른 세력의 유저도 공격할 수 있습니다."},
	{"","공격과 수비 인원 차이가 아무리 크더라도 거점 점령 조건은 언제나 “해당 거점을 지키는 마지막 NPC를 처치하는 것”입니다. 거점의 주인이 바뀌면 그 거점 안에 있는 다른 세력의 유저는 모두 제거되어 메인 신상으로 강제 이동됩니다."},
	{"","일정 조건을 충족하면 플레이어는 돌격, 포위 등 전술적 이동을 선택할 수 있습니다."},
	{"","세력전이 종료되면 가장 많은 거점을 점령한 세력이 최종 승리 세력이 됩니다."},
	{"","세력전이 종료되면 가장 많은 거점을 점령한 세력이 최종 승리 세력이 됩니다."},
	{"[전투]","[대기] 플레이어가 특정 영토에 들어가면 자동으로 대기 상태가 되며, 대기 상태에서는 적 플레이어와 매칭될 수 있고 매칭되면 전투가 시작됩니다."},
	{"","[적 탐색] 공격을 클릭하면 적 목표를 능동적으로 매칭하는 상태가 되며, 공격할 때마다 10초의 공격 쿨타임이 발생합니다. 공격 시 특정 세력의 플레이어를 선택해 공격할 수 있습니다."},
	{"","【전투】적 탐색 모드에서는 승리 후 30초의 CD 시간이 추가되며, 누적 시간이 1분에 도달하면 쿨다운 상태가 됩니다. 쿨다운 상태에서는 먼저 공격할 수 없으며, 기세 200을 소모하면 CD를 초기화할 수 있습니다. 전투 승리 후 플레이어의 닌자는 잃은 생명력을 회복하지 않지만 차크라는 초기화됩니다."},
	{"","[전사] 전투에서 패배하면 전사 상태가 되며, 전사 상태에서는 명령 관련 조작을 할 수 없습니다."},
	{"","【부활】전사하면 메인 신상으로 이동해 1분의 부활 쿨타임을 기다립니다. 기세 500을 소모하면 즉시 부활할 수 있습니다."},
	{"","[퇴각] 플레이어는 기세 200을 소모하고 최대 생명력의 20%를 잃는 대가로 교전 중인 영토에서 강제로 퇴각할 수 있습니다."},
	{"","[돌격] 공격 인원이 수비 인원의 2배를 넘으면 돌격 전술을 사용할 수 있습니다."},
	{"","[포위] 한 거점 주변의 거점들이 다른 세력에 점령되면, 해당 거점 내 수비 측이 입히는 피해가 50% 감소하고 받는 피해가 50% 증가합니다."},
	{"","[소집] 무신, 전신, 투신은 소집령을 발동하여 자기 세력 멤버를 신속히 집결시켜 목표 거점을 공격하도록 명령할 수 있습니다."},
	{"","[약자 지원] 세력전에서 2위를 하면 다음 세력전 기세가 1500 증가하고, 3위를 하면 다음 세력전 기세가 3000 증가합니다."},
	{"","[동맹] 한 세력이 세력전에서 연속 2회 1위를 하거나, 같은 세력이 연속 2회 3위를 하면, 지난 세력전의 2위와 3위가 자동으로 동맹을 맺습니다."},
	{"","[맹약] 세력전 정산 시 동맹을 맺은 두 세력의 거점 수와 총 명예를 합산해 순위를 매기며, 동맹 세력의 플레이어를 처치하면 개인 명예가 절반으로 줄어듭니다."},
	{"[보상]","명예치가 50 미만인 플레이어는 임무 보상을 받을 수 없습니다."},
	{"","세력전이 종료되면 세력이 점령한 영토 수에 따라 순위를 매기고, 세력전에서 명예 50 이상을 획득한 플레이어에게 일정한 보상을 지급합니다. 순위에 따라 보상이 다릅니다."},
	{"","세력전이 종료되면 개인 명예 순위에 따라 일정한 보상을 지급합니다."},
}

