-- Clone Breach Rules 
_activity_smoked_eggs_rule_tips = {
    "1. 이벤트 기간 중 누적 60 골드를 충전하면 분신 돌파용 쿠나이 1개를 얻으며, 하루 최대 10개까지 얻을 수 있습니다.\r\n\r\n2. 분신 돌파 1X에는 료*30000과 쿠나이*1이 소모되며, 3X, 6X, 10X 보상을 받을 기회가 있습니다. 즉 료* 90000, 료*180000, 료*300000입니다.\r\n\r\n3.진짜를 찾으면 10X 보상을 얻고, 분신 3개가 모두 초기화됩니다. 그렇지 않으면 계속해서 진짜를 찾아야 합니다 \r\n\r\n4.운이 좋으면 1번 만에 진짜를 찾아 10X 보상을 얻을 수 있으며, 그렇지 않더라도 3번 안에 10X 보상을 얻습니다. ",
    "1. 이벤트 기간 중 누적 60 골드를 충전하면 분신 돌파용 쿠나이 1개를 얻으며, 하루 최대 10개까지 얻을 수 있습니다.\r\n\r\n 2. 분신 돌파 1X에는 골드*10과 쿠나이*1이 소모되며, 3X, 6X, 10X 보상을 받을 기회가 있습니다. 즉 골드* 30, 골드*60, 골드*90입니다.\r\n\r\n3.진짜를 찾으면 10X 보상을 얻고, 분신 3개가 모두 초기화됩니다. 그렇지 않으면 계속해서 진짜를 찾아야 합니다.\r\n\r\n4. .운이 좋으면 1번 만에 진짜를 찾아 10X 보상을 얻을 수 있으며, 그렇지 않더라도 3번 안에 10X 보상을 얻습니다. ",
	}

