	"%d 레벨 사용 가능",			-- 15
	"1. 디지털 패스 이벤트는 1회당 30일간 진행됩니다.\r\n2. 경험치를 획득하면 패스 레벨이 올라가고 더 많은 보상이 개방됩니다.\r\n3. 디지털 패스 경험치는 일일 퀘스트와 주간 퀘스트를 완료하거나 충전으로 획득할 수 있으며, 충전 경험치 비율은 1:65입니다.\r\n4. 디지털 패스를 3회 연속 구매하면 고급 보상 1개를 무료로 개방할 수 있는 디지털 패스 개방 아이템을 받을 수 있습니다.\r\n5. 디지털 패스의 보상은 일반 보상과 고급 보상으로 나뉩니다. 일반 보상은 해당 패스 레벨에 도달하면 받을 수 있습니다. 고급 보상은 충전하거나 개방 아이템을 사용하고 해당 패스 레벨에 도달해야 받을 수 있습니다.\r\n6. 본 서버의 디지털 패스 구매 횟수가 지정 수치에 도달하면 서버의 모든 플레이어가 공용 구매 보상을 받습니다.\r\n7. 일반 상점과 특별 상점이 있으며, 일반 패스 골드 코인과 특별 패스 골드 코인으로 자원을 교환할 수 있습니다.\r\n8. 디지털 패스는 고급 보상만 개방할 수 있으며 다이아는 지급되지 않습니다. 동시에 VIP 경험치와 패스 경험치를 획득하고, 누적 충전과 충전 자원 진행도를 개방합니다.",	-- 16
	"1. 진행 패스는 스토리 퀘스트와 스토리 스테이지 두 종류로 나뉩니다. \r\n2. 진행 패스는 서로 다른 유형의 조건을 완료해 보상을 받을 수 있습니다.\r\n3. 진행 패스의 보상은 일반 보상과 고급 보상으로 나뉩니다. 일반 보상은 해당 패스 진행도에 도달하면 받을 수 있습니다. 고급 보상은 충전하거나 개방 아이템을 사용하고 해당 패스 진행도에 도달해야 받을 수 있습니다.\r\n4. 본 서버의 진행 패스 구매 횟수가 지정 수치에 도달하면 서버의 모든 플레이어가 공용 구매 보상을 받습니다. \r\n5. 공용 구매 보상의 구매 횟수는 같은 종류의 패스끼리만 누적되며, 다른 종류의 패스 구매 횟수는 공유되지 않습니다.\r\n6. 진행 패스는 고급 보상만 개방할 수 있으며 다이아는 지급되지 않습니다. 동시에 VIP 경험치와 패스 경험치를 획득하고, 누적 충전과 충전 자원 진행도를 개방합니다.\r\n7. 각 구간의 고급 보상은 각각 따로 구매해 개방해야 합니다.",				----17
